    var knee=anatomicalJoint(hip,hock,35,36,-1);
    keys=[{t:0,...top},{t:.23,...hip},{t:.56,...knee},{t:.82,...hock},{t:.92,...wrist},{t:1,x:p.x,y:p.y}];
