    var index=Math.round((((phase%1)+1)%1)*murphyFrameCount)%murphyFrameCount,frame=murphyFrames[index];
    ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(frame.base,0,0);
